/** Employer-generated 6-digit code; consumed on successful POST /api/jobs/:id/complete — Redis ก่อน แล้ว fallback Map */
const jobMeetCodes = new Map();
const JOB_MEET_REDIS_PREFIX = 'job:meet:';
function cleanupExpiredJobMeetCodes() {
  const now = Date.now();
  for (const [jid, row] of jobMeetCodes) {
    if (!row || row.expiresAt < now) jobMeetCodes.delete(jid);
  }
}
async function setJobMeetCodeEntry(jobId, payload) {
  const ttlSec = 15 * 60;
  if (redisClient) {
    await redisClient.setEx(JOB_MEET_REDIS_PREFIX + String(jobId), ttlSec, JSON.stringify(payload));
    return;
  }
  cleanupExpiredJobMeetCodes();
  jobMeetCodes.set(String(jobId), { ...payload, expiresAt: Date.now() + ttlSec * 1000 });
}
async function getJobMeetCodeEntry(jobId) {
  if (redisClient) {
    const raw = await redisClient.get(JOB_MEET_REDIS_PREFIX + String(jobId));
    if (!raw) return null;
    try {
      return JSON.parse(raw);
    } catch {
      return null;
    }
  }
  cleanupExpiredJobMeetCodes();
  const row = jobMeetCodes.get(String(jobId));
  if (!row || row.expiresAt < Date.now()) {
    jobMeetCodes.delete(String(jobId));
    return null;
  }
  return row;
}
async function deleteJobMeetCodeEntry(jobId) {
  if (redisClient) {
    await redisClient.del(JOB_MEET_REDIS_PREFIX + String(jobId)).catch(() => { });
  } else {
    jobMeetCodes.delete(String(jobId));
  }
}

function safeJsonObject(value) {
  if (!value) return {};
  try {
    return JSON.parse(JSON.stringify(value));
  } catch (_) {
    return {};
  }
}

async function appendFinancialDepositAudit({
  actorType = 'system',
  actorId = null,
  action,
  entityType = 'wallet_deposit_charge',
  entityId,
  reason = null,
  correlationId = null,
  externalRef = null,
  stateAfter = null,
}) {
  try {
    if (!action || !entityType || !entityId) return;
    await pool.query(
      `INSERT INTO financial_audit_log
       (actor_type, actor_id, action, entity_type, entity_id, reason, correlation_id, external_ref, state_after)
       VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)`,
      [
        actorType,
        actorId,
        String(action),
        String(entityType),
        String(entityId),
        reason ? String(reason) : null,
        correlationId ? String(correlationId) : null,
        externalRef ? String(externalRef) : null,
        stateAfter ? safeJsonObject(stateAfter) : null,
      ]
    );
  } catch (_) {
    // Financial audit trace is best-effort and must not break payment flow.
  }
}

async function appendWalletDepositWebhookLog({
  provider = 'payso',
  chargeId = null,
  referenceId = null,
  transactionId = null,
  userId = null,
  sourceType = null,
  amount = null,
  eventStatus = null,
  httpStatus = null,
  signatureValid = null,
  bypassUnsigned = false,
  headers = null,
  payload = null,
  rawBody = null,
  processingResult = null,
}) {
  try {
    await pool.query(
      `INSERT INTO wallet_deposit_webhook_logs
       (provider, charge_id, reference_id, transaction_id, user_id, source_type, amount, event_status, http_status, signature_valid, bypass_unsigned, headers_json, payload_json, raw_body, processing_result)
       VALUES ($1, $2, $3, $4, $5::uuid, $6, $7, $8, $9, $10, $11, $12::jsonb, $13::jsonb, $14, $15::jsonb)`,
      [
        provider,
        chargeId || null,
        referenceId || null,
        transactionId || null,
        userId || null,
        sourceType || null,
        Number.isFinite(Number(amount)) ? Number(amount) : null,
        eventStatus || null,
        Number.isFinite(Number(httpStatus)) ? Number(httpStatus) : null,
        typeof signatureValid === 'boolean' ? signatureValid : null,
        bypassUnsigned === true,
        JSON.stringify(safeJsonObject(headers)),
        JSON.stringify(safeJsonObject(payload)),
        typeof rawBody === 'string' ? rawBody.slice(0, 8000) : null,
        JSON.stringify(safeJsonObject(processingResult)),
      ]
    );
  } catch (_) {
    // Webhook log persistence is best-effort.
  }
}

